using namespace std::literals;

namespace graphql::tagimg {
namespace object {

Query::Query(std::unique_ptr<const Concept> pimpl) noexcept
    : service::Object{getTypeNames(), getResolvers()}, _schema{GetSchema()},
      _pimpl{std::move(pimpl)} {
}

service::TypeNames Query::getTypeNames() const noexcept {
  return {R"gql(Query)gql"sv};
}

service::ResolverMap Query::getResolvers() const noexcept {
  return {{R"gql(ping)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolvePing(std::move(params));
           }},
          {R"gql(__type)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolve_type(std::move(params));
           }},
          {R"gql(artwork)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveArtwork(std::move(params));
           }},
          {R"gql(__schema)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolve_schema(std::move(params));
           }},
          {R"gql(artworks)gql"sv,
           [this](service::ResolverParams &&params) {
             return resolveArtworks(std::move(params));
           }},
          {R"gql(__typename)gql"sv, [this](service::ResolverParams &&params) {
             return resolve_typename(std::move(params));
           }}};
}

void Query::beginSelectionSet(const service::SelectionSetParams &params) const {
  _pimpl->beginSelectionSet(params);
}

void Query::endSelectionSet(const service::SelectionSetParams &params) const {
  _pimpl->endSelectionSet(params);
}

service::AwaitableResolver
Query::resolvePing(service::ResolverParams &&params) const {
  std::unique_lock resolverLock(_resolverMutex);
  service::SelectionSetParams selectionSetParams{
      static_cast<const service::SelectionSetParams &>(params)};
  auto directives = std::move(params.fieldDirectives);
  auto result = _pimpl->getPing(service::FieldParams{
      std::move(selectionSetParams), std::move(directives)});
  resolverLock.unlock();

  return service::ModifiedResult<std::string>::convert(std::move(result),
                                                       std::move(params));
}

service::AwaitableResolver
Query::resolveArtwork(service::ResolverParams &&params) const {
  auto argId = service::ModifiedArgument<response::IdType>::require(
      "id", params.arguments);
  std::unique_lock resolverLock(_resolverMutex);
  service::SelectionSetParams selectionSetParams{
      static_cast<const service::SelectionSetParams &>(params)};
  auto directives = std::move(params.fieldDirectives);
  auto result =
      _pimpl->getArtwork(service::FieldParams{std::move(selectionSetParams),
                                              std::move(directives)},
                         std::move(argId));
  resolverLock.unlock();

  return service::ModifiedResult<Artwork>::convert<
      service::TypeModifier::Nullable>(std::move(result), std::move(params));
}

service::AwaitableResolver
Query::resolveArtworks(service::ResolverParams &&params) const {
  static const auto defaultArguments = []() {
    response::Value values(response::Type::Map);
    response::Value entry;

    entry = response::Value(response::Type::EnumValue);
    entry.set<std::string>(R"gql(CREATED_AT)gql");
    values.emplace_back("orderBy", std::move(entry));
    entry = response::Value(response::Type::EnumValue);
    entry.set<std::string>(R"gql(DESC)gql");
    values.emplace_back("direction", std::move(entry));
    entry = response::Value(static_cast<int>(20));
    values.emplace_back("limit", std::move(entry));
    entry = response::Value(static_cast<int>(0));
    values.emplace_back("offset", std::move(entry));
    entry = response::Value(false);
    values.emplace_back("includeTotal", std::move(entry));

    return values;
  }();

  auto argFilter = service::ModifiedArgument<tagimg::ArtworkFilter>::require<
      service::TypeModifier::Nullable>("filter", params.arguments);
  auto pairOrderBy = service::ModifiedArgument<tagimg::ArtworkOrderField>::find<
      service::TypeModifier::Nullable>("orderBy", params.arguments);
  auto argOrderBy =
      (pairOrderBy.second
           ? pairOrderBy.first
           : service::ModifiedArgument<tagimg::ArtworkOrderField>::require<
                 service::TypeModifier::Nullable>("orderBy", defaultArguments));
  auto pairDirection = service::ModifiedArgument<tagimg::SortDirection>::find<
      service::TypeModifier::Nullable>("direction", params.arguments);
  auto argDirection =
      (pairDirection.second
           ? pairDirection.first
           : service::ModifiedArgument<tagimg::SortDirection>::require<
                 service::TypeModifier::Nullable>("direction",
                                                  defaultArguments));
  auto pairLimit =
      service::ModifiedArgument<int>::find<service::TypeModifier::Nullable>(
          "limit", params.arguments);
  auto argLimit =
      (pairLimit.second
           ? std::move(pairLimit.first)
           : service::ModifiedArgument<int>::require<
                 service::TypeModifier::Nullable>("limit", defaultArguments));
  auto pairOffset =
      service::ModifiedArgument<int>::find<service::TypeModifier::Nullable>(
          "offset", params.arguments);
  auto argOffset =
      (pairOffset.second
           ? std::move(pairOffset.first)
           : service::ModifiedArgument<int>::require<
                 service::TypeModifier::Nullable>("offset", defaultArguments));
  auto pairIncludeTotal =
      service::ModifiedArgument<bool>::find<service::TypeModifier::Nullable>(
          "includeTotal", params.arguments);
  auto argIncludeTotal =
      (pairIncludeTotal.second ? std::move(pairIncludeTotal.first)
                               : service::ModifiedArgument<bool>::require<
                                     service::TypeModifier::Nullable>(
                                     "includeTotal", defaultArguments));
  std::unique_lock resolverLock(_resolverMutex);
  service::SelectionSetParams selectionSetParams{
      static_cast<const service::SelectionSetParams &>(params)};
  auto directives = std::move(params.fieldDirectives);
  auto result = _pimpl->getArtworks(
      service::FieldParams{std::move(selectionSetParams),
                           std::move(directives)},
      std::move(argFilter), std::move(argOrderBy), std::move(argDirection),
      std::move(argLimit), std::move(argOffset), std::move(argIncludeTotal));
  resolverLock.unlock();

  return service::ModifiedResult<ArtworkConnection>::convert(std::move(result),
                                                             std::move(params));
}

service::AwaitableResolver
Query::resolve_typename(service::ResolverParams &&params) const {
  return service::Result<std::string>::convert(std::string{R"gql(Query)gql"},
                                               std::move(params));
}

service::AwaitableResolver
Query::resolve_schema(service::ResolverParams &&params) const {
  return service::Result<service::Object>::convert(
      std::static_pointer_cast<service::Object>(
          std::make_shared<introspection::object::Schema>(
              std::make_shared<introspection::Schema>(_schema))),
      std::move(params));
}

service::AwaitableResolver
Query::resolve_type(service::ResolverParams &&params) const {
  auto argName =
      service::ModifiedArgument<std::string>::require("name", params.arguments);
  const auto &baseType = _schema->LookupType(argName);
  std::shared_ptr<introspection::object::Type> result{
      baseType ? std::make_shared<introspection::object::Type>(
                     std::make_shared<introspection::Type>(baseType))
               : nullptr};

  return service::ModifiedResult<introspection::object::Type>::convert<
      service::TypeModifier::Nullable>(result, std::move(params));
}

} // namespace object

void AddQueryDetails(const std::shared_ptr<schema::ObjectType> &typeQuery,
                     const std::shared_ptr<schema::Schema> &schema) {
  typeQuery->AddFields(
      {schema::Field::Make(
           R"gql(ping)gql"sv, R"md(服务健康检查，始终返回 ok。)md"sv,
           std::nullopt,
           schema->WrapType(introspection::TypeKind::NON_NULL,
                            schema->LookupType(R"gql(String)gql"sv))),
       schema::Field::Make(
           R"gql(artwork)gql"sv, R"md(按作品 ID 查询单条作品。

ID 必须是合法 UUID，否则返回 INVALID_ARGUMENT 错误；
作品不存在时返回 null，而不是错误。)md"sv,
           std::nullopt, schema->LookupType(R"gql(Artwork)gql"sv),
           {schema::InputValue::Make(
               R"gql(id)gql"sv, R"md()md"sv,
               schema->WrapType(introspection::TypeKind::NON_NULL,
                                schema->LookupType(R"gql(ID)gql"sv)),
               R"gql()gql"sv)}),
       schema::Field::Make(
           R"gql(artworks)gql"sv, R"md(分页查询已入库的作品。

所有过滤条件之间是 AND 关系；同一个数组内部是 OR 关系。)md"sv,
           std::nullopt,
           schema->WrapType(introspection::TypeKind::NON_NULL,
                            schema->LookupType(R"gql(ArtworkConnection)gql"sv)),
           {schema::InputValue::Make(
                R"gql(filter)gql"sv, R"md(过滤条件，缺省时返回全部作品。)md"sv,
                schema->LookupType(R"gql(ArtworkFilter)gql"sv), R"gql()gql"sv),
            schema::InputValue::Make(
                R"gql(orderBy)gql"sv, R"md(排序字段，默认按创建时间。)md"sv,
                schema->LookupType(R"gql(ArtworkOrderField)gql"sv),
                R"gql(CREATED_AT)gql"sv),
            schema::InputValue::Make(
                R"gql(direction)gql"sv, R"md(排序方向，默认倒序。)md"sv,
                schema->LookupType(R"gql(SortDirection)gql"sv),
                R"gql(DESC)gql"sv),
            schema::InputValue::Make(
                R"gql(limit)gql"sv, R"md(每页数量，1 到 100。)md"sv,
                schema->LookupType(R"gql(Int)gql"sv), R"gql(20)gql"sv),
            schema::InputValue::Make(
                R"gql(offset)gql"sv, R"md(跳过数量，0 到 10000。)md"sv,
                schema->LookupType(R"gql(Int)gql"sv), R"gql(0)gql"sv),
            schema::InputValue::Make(
                R"gql(includeTotal)gql"sv,
                R"md(是否统计总数；为 true 时 total 才有值。)md"sv,
                schema->LookupType(R"gql(Boolean)gql"sv),
                R"gql(false)gql"sv)})});
}

} // namespace graphql::tagimg
